/* @autogenerated */
package net.civeira.phylax.testing.sql;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import javax.sql.DataSource;

import org.h2.jdbcx.JdbcDataSource;

/**
 * An H2 database on memory (in MariaDB mode) with the schema of the application, built from the
 * mysql migrations of the classpath: the unit tests of the sql adapters run the real sentences
 * without a database server.
 *
 * <p>
 * Each instance is a new and empty database.
 */
public class H2Database {
  private static final String CHANGELOG = "migration/mysql/changelog.txt";
  private static final String KEYWORDS = "USER,VALUE,KEY,CURRENT,YEAR,MONTH,DAY,HOUR,MINUTE,"
      + "SECOND,TYPE,ORDER,GROUPS,SESSION,ROLE,STATUS,LIMIT,OFFSET";
  private static final Pattern INDEX =
      Pattern.compile("(?i)^(CREATE\\s+(?:UNIQUE\\s+)?INDEX\\s+)(\\w+)(\\s+ON\\s+)(\\w+)");

  private static final com.fasterxml.jackson.databind.ObjectMapper MAPPER =
      new com.fasterxml.jackson.databind.ObjectMapper();

  private final JdbcDataSource dataSource;

  public H2Database() {
    dataSource = new JdbcDataSource();
    dataSource.setURL("jdbc:h2:mem:" + UUID.randomUUID() + ";MODE=MariaDB;DATABASE_TO_LOWER=TRUE"
        + ";DB_CLOSE_DELAY=-1;NON_KEYWORDS=" + KEYWORDS);
    try (Connection connection = dataSource.getConnection();
        Statement statement = connection.createStatement()) {
      // The json functions of mysql used by the adapters.
      statement.execute(
          "CREATE ALIAS JSON_EXTRACT FOR \"" + H2Database.class.getName() + ".jsonExtract\"");
      statement.execute(
          "CREATE ALIAS JSON_UNQUOTE FOR \"" + H2Database.class.getName() + ".jsonUnquote\"");
      for (String file : resource(CHANGELOG).split("\\R")) {
        if (file.isBlank()) {
          continue;
        }
        for (String sql : statements(resource(file.trim().replaceFirst("^/", "")))) {
          try {
            statement.execute(adapt(sql));
          } catch (SQLException ex) {
            throw new IllegalStateException("Unable to apply on h2 " + file + ": " + sql, ex);
          }
        }
      }
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  /** If the application has the mysql migrations to build the schema. */
  public static boolean available() {
    return null != H2Database.class.getClassLoader().getResource(CHANGELOG);
  }

  /**
   * The datasource of the database: the sentences are adapted to the few differences of h2 with
   * mariadb (the type of a parameter on the selected values must be declared).
   */
  public DataSource dataSource() {
    return (DataSource) java.lang.reflect.Proxy.newProxyInstance(H2Database.class.getClassLoader(),
        new Class<?>[] {DataSource.class}, (self, method, args) -> {
          Object result = invoke(dataSource, method, args);
          return result instanceof Connection connection ? connection(connection) : result;
        });
  }

  private static Connection connection(Connection connection) {
    return (Connection) java.lang.reflect.Proxy.newProxyInstance(H2Database.class.getClassLoader(),
        new Class<?>[] {Connection.class}, (self, method, args) -> {
          if (method.getName().equals("prepareStatement") && null != args
              && args[0] instanceof String sql) {
            args[0] = h2(sql);
          }
          return invoke(connection, method, args);
        });
  }

  private static Object invoke(Object target, java.lang.reflect.Method method, Object[] args)
      throws Throwable {
    try {
      return method.invoke(target, args);
    } catch (java.lang.reflect.InvocationTargetException ex) {
      throw ex.getCause();
    }
  }

  private static final Pattern SELECTED = Pattern.compile("(?is)\\bSELECT\\b(.*?)\\bFROM\\b");

  /** Declare the type of the parameters on the selected values ("SELECT a, ?, 'b' FROM"). */
  static String h2(String sql) {
    Matcher matcher = SELECTED.matcher(sql);
    StringBuilder result = new StringBuilder();
    while (matcher.find()) {
      String fields = matcher.group(1).replaceAll("(?<![\\w'])\\?(?![\\w'])", "CAST(? AS VARCHAR)");
      matcher.appendReplacement(result, Matcher.quoteReplacement("SELECT" + fields + "FROM"));
    }
    matcher.appendTail(result);
    return result.toString();
  }

  /** Run a sentence on the database (to prepare data). */
  public void execute(String sql) {
    try (Connection connection = dataSource.getConnection();
        Statement statement = connection.createStatement()) {
      statement.execute(sql);
    } catch (SQLException ex) {
      throw new IllegalStateException(sql, ex);
    }
  }

  /** Count the rows of a table matching a condition (or all with null). */
  public long count(String table, String where) {
    try (Connection connection = dataSource.getConnection();
        Statement statement = connection.createStatement();
        var rs = statement.executeQuery(
            "SELECT COUNT(*) FROM " + table + (null == where ? "" : " WHERE " + where))) {
      rs.next();
      return rs.getLong(1);
    } catch (SQLException ex) {
      throw new IllegalStateException(ex);
    }
  }

  /** JSON_EXTRACT(doc, '$.a.b') of mysql: the json of the value on the path (or null). */
  public static String jsonExtract(String json, String path) {
    if (null == json || null == path) {
      return null;
    }
    try {
      com.fasterxml.jackson.databind.JsonNode node = MAPPER.readTree(json);
      for (String part : path.replaceFirst("^\\$\\.?", "").split("\\.")) {
        if (part.isEmpty()) {
          continue;
        }
        node = null == node ? null : node.get(part);
      }
      return null == node || node.isMissingNode() ? null : MAPPER.writeValueAsString(node);
    } catch (IOException ex) {
      return null;
    }
  }

  /** JSON_UNQUOTE of mysql: the text of a json string. */
  public static String jsonUnquote(String json) {
    if (null == json) {
      return null;
    }
    try {
      com.fasterxml.jackson.databind.JsonNode node = MAPPER.readTree(json);
      return node.isTextual() ? node.asText() : json;
    } catch (IOException ex) {
      return json;
    }
  }

  private static String adapt(String sql) {
    Matcher index = INDEX.matcher(sql);
    if (index.find()) {
      // The index names are unique by table on mysql, but by schema on h2.
      return index.replaceFirst("$1$2__$4$3$4");
    }
    return sql;
  }

  private static List<String> statements(String script) {
    List<String> result = new ArrayList<>();
    StringBuilder current = new StringBuilder();
    for (String line : script.split("\\R")) {
      String trimmed = line.trim();
      if (trimmed.startsWith("--") || trimmed.isEmpty()) {
        continue;
      }
      current.append(line).append('\n');
      if (trimmed.endsWith(";")) {
        String sql = current.toString().trim();
        result.add(sql.substring(0, sql.length() - 1));
        current.setLength(0);
      }
    }
    if (!current.toString().isBlank()) {
      result.add(current.toString().trim());
    }
    return result;
  }

  private static String resource(String name) {
    try (InputStream in = H2Database.class.getClassLoader().getResourceAsStream(name)) {
      if (null == in) {
        throw new IllegalStateException("No resource " + name);
      }
      return new String(in.readAllBytes(), StandardCharsets.UTF_8);
    } catch (IOException ex) {
      throw new IllegalStateException(ex);
    }
  }
}
